year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "李珽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷264天复三年条所见人物：李珽。", "biography": null, "status": "draft", "id": "eee3e8f9-b8eb-571e-9520-2d58cf9bb6da"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "马宾", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：马宾。", "biography": null, "status": "draft", "id": "1aa82a92-8993-5b15-a976-f874f6880e85"}, {"name": "马存", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷266开平二年条所见人物：马存。", "biography": null, "status": "draft", "id": "86a4c44a-e9ca-5b3a-b73e-c066692db428"}, {"name": "高季昌", "aliases": ["高季兴"], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“高季昌受命为荆南节度使”中为受任者。", "biography": null, "status": "draft", "id": "e1d9e2c4-6e41-5d7c-8d65-eb79a2407418"}, {"name": "敖骈", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：敖骈。", "biography": null, "status": "draft", "id": "a0fa5d2e-f9a1-5ab5-8e6d-efdfd924a325"}, {"name": "彭瑊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：彭瑊。", "biography": null, "status": "draft", "id": "b2b88cb1-2d28-5b24-89e0-c11a292c587c"}, {"name": "彭玕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“楚军与彭玕进攻洪州未克”中为进攻者。", "biography": null, "status": "draft", "id": "4f82f7a8-f1bc-5880-a292-580b33cb7a63"}]'::jsonb)
